from typing import List

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx = self.find(x)
        ry = self.find(y)
        if rx == ry:
            return False
        if self.size[rx] < self.size[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        self.size[rx] += self.size[ry]
        return True

    def get_size(self, x):
        rx = self.find(x)
        return self.size[rx]

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m = len(grid)
        n = len(grid[0])
        total = m * n
        top = total  # virtual top node index

        # copy original grid
        orig = [row[:] for row in grid]
        # apply all hits to create the grid after all removals
        grid_after = [row[:] for row in grid]
        for r, c in hits:
            if 0 <= r < m and 0 <= c < n and grid_after[r][c] == 1:
                grid_after[r][c] = 0

        dsu = DSU(total + 1)

        def idx(r, c):
            return r * n + c

        # union all bricks in grid_after
        for r in range(m):
            for c in range(n):
                if grid_after[r][c] == 1:
                    id1 = idx(r, c)
                    # union to top if in top row
                    if r == 0:
                        dsu.union(id1, top)
                    # union with up and left to avoid duplicates
                    if r > 0 and grid_after[r-1][c] == 1:
                        dsu.union(id1, idx(r-1, c))
                    if c > 0 and grid_after[r][c-1] == 1:
                        dsu.union(id1, idx(r, c-1))

        res = [0] * len(hits)
        # process hits in reverse
        for i in range(len(hits)-1, -1, -1):
            r, c = hits[i]
            # if original had no brick, nothing changes
            if orig[r][c] == 0:
                res[i] = 0
                continue
            # record size of top component before adding back
            prev_top_size = dsu.get_size(top)
            # add the brick back
            pos = idx(r, c)
            # mark as present by logically treating as node with size 1 (already initialized)
            # union with neighbors that are bricks in grid_after (current state)
            # but first set grid_after[r][c] = 1 to reflect presence for subsequent unions
            grid_after[r][c] = 1
            if r == 0:
                dsu.union(pos, top)
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and grid_after[nr][nc] == 1:
                    dsu.union(pos, idx(nr, nc))
            new_top_size = dsu.get_size(top)
            # newly connected bricks = new_top_size - prev_top_size
            # exclude the brick we just added
            fallen = max(0, new_top_size - prev_top_size - 1)
            res[i] = fallen

        return res
